def load(p):return json.loads(Path(p).read_text(encoding='utf-8-sig'))
def clean(value):
 if isinstance(value,dict):return {k:clean(v) for k,v in value.items()}
 if isinstance(value,list):return [clean(v) for v in value]
 if pd.isna(value):return None
 if hasattr(value,'item'):return value.item()
 return value
def query(rows,label,path,definitions):return {'rows':rows,'source':{'label':label,'path':str(path),'filters':['R148v2 formal scratch run; latest available frozen evidence at report build'],'metricDefinitions':definitions}}
def main():
 training=load(OUT/'training_snapshot.json');frozen=load(OUT/'frozen_checkpoint_audit.json');drivers=load(OUT/'dev_driver_summary.json');dev=pd.read_csv(OUT/'dev_curve.csv');devcat=pd.read_csv(OUT/'dev_category_curve.csv');share=pd.read_csv(OUT/'weighted_loss_contributions.csv');latest_step=int(dev.step.max());latest=devcat[devcat.step==latest_step].copy();initial=devcat[devcat.step==0][['category','loss_mean']].rename(columns={'loss_mean':'initial_loss'});latest=latest.merge(initial,on='category');latest['improvement_percent']=100*(latest.initial_loss-latest.loss_mean)/latest.initial_loss;latest['latest_share_pct']=100*latest.loss_mean*latest['count']/(latest.loss_mean*latest['count']).sum();stage=pd.DataFrame(frozen['stage_summary']);ablation=pd.DataFrame(frozen['ablation_summary']);params=pd.DataFrame(frozen['parameter_groups']);grad=load(OUT/'objective_gradient_audit.json') if (OUT/'objective_gradient_audit.json').exists() else {'norms':[],'cosines':[]};real_path=ROOT/'results/real_validation_summary.json';real=load(real_path) if real_path.exists() else None;real_ranking=pd.read_csv(ROOT/'results/real_validation_ranking.csv') if real else pd.DataFrame()
